module case_range_1(input logic clk, rst, en, output logic [3:0] value);
always_ff @(posedge clk or posedge rst) begin
  if (rst) value <= 0;
  else begin
    case(value) inside
      [0:3]: if (en) value <= value + 1;
      [4:7]: if (en) value <= value - 1;
      [8:11]: value <= 4'b0101;
      [12:15]: value <= 0;
    endcase
  end
end
endmodule

module case_range_2(input logic clk, rst, inc, dec, output logic [2:0] level);
always_ff @(posedge clk or posedge rst) begin
  if (rst) level <= 3'b011;
  else begin
    case(level) inside
      [0:2]: begin
        if (inc) level <= level + 1;
        if (dec) level <= level - 1;
      end
      [3:5]: level <= 3'b010;
      [6:7]: level <= 3'b011;
    endcase
  end
end
endmodule

module case_set_1(input logic clk, rst, trigger, output logic [2:0] pattern);
always_ff @(posedge clk or posedge rst) begin
  if (rst) pattern <= 3'b001;
  else begin
    case(pattern) inside
      {3'b001, 3'b010, 3'b100}: if (trigger) pattern <= pattern << 1;
      3'b110, 3'b101, 3'b011: pattern <= 3'b111;
      3'b111: pattern <= 3'b001;
    endcase
  end
end
endmodule

module case_set_2(input logic clk, rst, mode, output logic [1:0] state);
always_ff @(posedge clk or posedge rst) begin
  if (rst) state <= 2'b00;
  else begin
    case(state) inside
      {2'b00, 2'b11}: state <= mode ? 2'b01 : 2'b10;
      {2'b01, 2'b10}: state <= state ^ 2'b11;
    endcase
  end
end
endmodule

module casex_example(input logic clk, rst, ctrl, output logic [3:0] data);
always_ff @(posedge clk or posedge rst) begin
  if (rst) data <= 4'b0000;
  else begin
    casex(data)
      4'b000x: data <= ctrl ? 4'b0010 : 4'b0001;
      4'b001x: data <= data | 4'b1100;
      4'b01xx: data <= {data[2:0], 1'b0};
      4'b1xxx: data <= 4'b0000;
      default: data <= data;
    endcase
  end
end
endmodule

module casez_example(input logic clk, rst, update, output logic [3:0] mask);
always_ff @(posedge clk or posedge rst) begin
  if (rst) mask <= 4'b0001;
  else begin
    casez(mask)
      4'b000?: mask <= mask << 1;
      4'b001?: mask <= update ? 4'b0100 : 4'b0010;
      4'b01??: mask <= mask | 4'b1000;
      4'b1???: mask <= 4'b0001;
    endcase
  end
end
endmodule

module case_range_mixed(input logic clk, rst, sel, output logic [4:0] counter);
always_ff @(posedge clk or posedge rst) begin
  if (rst) counter <= 5'd0;
  else begin
    case(counter) inside
      [0:7], [24:31]: counter <= counter + 1;
      [8:15]: counter <= sel ? counter - 1 : counter + 2;
      [16:23]: counter <= 5'd0;
    endcase
  end
end
endmodule

module case_set_mixed(input logic clk, rst, a, b, output logic [2:0] code);
always_ff @(posedge clk or posedge rst) begin
  if (rst) code <= 3'b000;
  else begin
    case(code) inside
      {3'b000, 3'b111}: code <= a ? 3'b001 : 3'b110;
      {3'b001, 3'b010}: code <= b ? code + 1 : code - 1;
      {3'b011, 3'b100, 3'b101, 3'b110}: code <= 3'b000;
    endcase
  end
end
endmodule

module casex_range(input logic clk, rst, en, output logic [5:0] value);
always_ff @(posedge clk or posedge rst) begin
  if (rst) value <= 6'b000001;
  else begin
    casex(value)
      6'b0000xx: value <= en ? value << 1 : value;
      6'b0001xx: value <= value + 1;
      6'b001xxx: value <= value | 6'b110000;
      6'b01xxxx: value <= 6'b000001;
      6'b1xxxxx: value <= value & 6'b011111;
    endcase
  end
end
endmodule

module casez_set(input logic clk, rst, trigger, output logic [3:0] seq);
always_ff @(posedge clk or posedge rst) begin
  if (rst) seq <= 4'b0001;
  else begin
    casez(seq)
      4'b0001, 4'b0010, 4'b0100: seq <= seq << 1;
      4'b1000: seq <= trigger ? 4'b0011 : 4'b1100;
      4'b00??: seq <= 4'b0100;
      4'b??1?: seq <= seq ^ 4'b1010;
      4'b1???: seq <= 4'b0001;
    endcase
  end
end
endmodule

module case_bitwise(input logic clk, rst, toggle, output logic [7:0] data);
always_ff @(posedge clk or posedge rst) begin
  if (rst) data <= 8'hAA;
  else begin
    case(data[1:0])
      2'b00: data <= toggle ? data ^ 8'hFF : data;
      2'b01: data <= data | 8'h55;
      2'b10: data <= data & 8'hF0;
      2'b11: data <= {data[6:0], data[7]};
    endcase
  end
end
endmodule

module case_offset(input logic clk, rst, adjust, output logic [4:0] offset);
always_ff @(posedge clk or posedge rst) begin
  if (rst) offset <= 5'd8;
  else begin
    case(offset) inside
      [0:4]: offset <= adjust ? offset + 3 : offset;
      [5:9]: offset <= offset - 2;
      [10:14]: offset <= 5'd15;
      [15:19]: offset <= offset - 5;
      [20:31]: offset <= 5'd0;
    endcase
  end
end
endmodule

module case_priority(input logic clk, rst, req_a, req_b, req_c, output logic [2:0] grant);
always_ff @(posedge clk or posedge rst) begin
  if (rst) grant <= 3'b000;
  else begin
    case(1'b1)
      req_a: grant <= 3'b001;
      req_b: grant <= 3'b010;
      req_c: grant <= 3'b100;
      default: grant <= 3'b000;
    endcase
  end
end
endmodule

module case_wrap(input logic clk, rst, inc, wrap, output logic [3:0] pointer);
always_ff @(posedge clk or posedge rst) begin
  if (rst) pointer <= 4'b0000;
  else begin
    case(pointer)
      4'b0000: pointer <= inc ? 4'b0001 : pointer;
      4'b1111: pointer <= wrap ? 4'b0000 : 4'b1110;
      default: pointer <= inc ? pointer + 1 : pointer - 1;
    endcase
  end
end
endmodule

module case_multi_cond(input logic clk, rst, cond1, cond2, output logic [2:0] mode);
always_ff @(posedge clk or posedge rst) begin
  if (rst) mode <= 3'b000;
  else begin
    case({cond1, cond2})
      2'b00: mode <= mode;
      2'b01: mode <= mode | 3'b001;
      2'b10: mode <= mode & 3'b110;
      2'b11: mode <= mode ^ 3'b011;
    endcase
  end
end
endmodule

module case_threshold(input logic clk, rst, add, sub, output logic [5:0] threshold);
always_ff @(posedge clk or posedge rst) begin
  if (rst) threshold <= 6'd20;
  else begin
    case(threshold) inside
      [0:10]: threshold <= add ? threshold + 5 : threshold;
      [11:30]: begin
        if (add) threshold <= threshold + 2;
        if (sub) threshold <= threshold - 1;
      end
      [31:40]: threshold <= sub ? threshold - 3 : threshold;
      [41:63]: threshold <= 6'd20;
    endcase
  end
end
endmodule

module case_pattern_gen(input logic clk, rst, next, output logic [7:0] pattern);
always_ff @(posedge clk or posedge rst) begin
  if (rst) pattern <= 8'b10101010;
  else begin
    case(pattern[3:0])
      4'b0000: pattern <= 8'b01010101;
      4'b0101: pattern <= 8'b00110011;
      4'b1010: pattern <= 8'b11001100;
      4'b1111: pattern <= 8'b00001111;
      default: if (next) pattern <= {pattern[6:0], pattern[7]};
    endcase
  end
end
endmodule

module case_window(input logic clk, rst, slide, output logic [3:0] window);
always_ff @(posedge clk or posedge rst) begin
  if (rst) window <= 4'b1000;
  else begin
    case(window) inside
      {4'b1000, 4'b0100, 4'b0010, 4'b0001}:
        window <= slide ? {window[0], window[3:1]} : window;
      default: window <= 4'b1000;
    endcase
  end
end
endmodule

module case_lfsr(input logic clk, rst, seed_en, output logic [7:0] lfsr);
always_ff @(posedge clk or posedge rst) begin
  if (rst) lfsr <= 8'h01;
  else begin
    case(lfsr[0])
      1'b0: lfsr <= {lfsr[0] ^ lfsr[2] ^ lfsr[3] ^ lfsr[4], lfsr[7:1]};
      1'b1: begin
        if (seed_en) lfsr <= 8'hA5;
        else lfsr <= {lfsr[0] ^ lfsr[6], lfsr[7:1]};
      end
    endcase
  end
end
endmodule

module case_delay(input logic clk, rst, start, output logic [2:0] delay);
always_ff @(posedge clk or posedge rst) begin
  if (rst) delay <= 3'b000;
  else begin
    case(delay)
      3'b000: delay <= start ? 3'b001 : 3'b000;
      3'b001: delay <= 3'b010;
      3'b010: delay <= 3'b100;
      3'b100: delay <= 3'b000;
      default: delay <= 3'b000;
    endcase
  end
end
endmodule

module case_amplitude(input logic clk, rst, up, down, output logic [4:0] amplitude);
always_ff @(posedge clk or posedge rst) begin
  if (rst) amplitude <= 5'd16;
  else begin
    case(amplitude) inside
      [0:7]: amplitude <= up ? amplitude + 4 : amplitude;
      [8:15]: begin
        if (up) amplitude <= amplitude + 2;
        if (down) amplitude <= amplitude - 1;
      end
      [16:23]: amplitude <= down ? amplitude - 2 : amplitude;
      [24:31]: amplitude <= 5'd16;
    endcase
  end
end
endmodule

module case_edge_det(input logic clk, rst, sig, output logic [1:0] edge_state);
always_ff @(posedge clk or posedge rst) begin
  if (rst) edge_state <= 2'b00;
  else begin
    case(edge_state)
      2'b00: edge_state <= sig ? 2'b01 : 2'b00;
      2'b01: edge_state <= sig ? 2'b11 : 2'b10;
      2'b10: edge_state <= sig ? 2'b01 : 2'b00;
      2'b11: edge_state <= sig ? 2'b11 : 2'b10;
    endcase
  end
end
endmodule

module case_rotation(input logic clk, rst, dir, output logic [5:0] rotator);
always_ff @(posedge clk or posedge rst) begin
  if (rst) rotator <= 6'b000111;
  else begin
    case(rotator[2:0])
      3'b000: rotator <= dir ? {rotator[4:0], rotator[5]} : {rotator[0], rotator[5:1]};
      3'b111: rotator <= 6'b111000;
      3'b001, 3'b010, 3'b100: rotator <= rotator ^ 6'b101010;
      default: rotator <= rotator + 1;
    endcase
  end
end
