  else begin
    case(bias) inside
      [0:3]: begin
        if (inc) bias <= bias + 2;
        if (dec) bias <= (bias == 0) ? 0 : bias - 1;
      end
      [4:11]: begin
        if (inc && bias < 4'b1111) bias <= bias + 1;
        if (dec && bias > 4'b0000) bias <= bias - 1;
      end
      [12:15]: begin
        if (inc) bias <= 4'b1111;
        if (dec) bias <= bias - 2;
